    const e0=ring[0],e1=ring[1],el=Math.hypot(e1[0]-e0[0],e1[1]-e0[1])||1,out=inPoly((e0[0]+e1[0])/2+(e1[1]-e0[1])/el*0.3,(e0[1]+e1[1])/2-(e1[0]-e0[0])/el*0.3,ring)?-1:1;   // +1 when (dz,-dx) points outside
